const tbody=document.querySelector('#tagRows'),empty=document.querySelector('#emptyState'),count=document.querySelector('#resultCount');
function render(){const q=document.querySelector('#searchInput').value.trim().toLowerCase(),g=document.querySelector('#groupFilter').value,s=document.querySelector('#statusFilter').value;const list=tags.filter(t=>(!q||(t.name+t.desc).toLowerCase().includes(q))&&(!g||t.group===g)&&(!s||(s==='enabled')===t.enabled));tbody.innerHTML=list.map(t=>`<tr data-id="${t.id}"><td><input type="checkbox" aria-label="选择 ${t.name}"></td><td><div class="tag-cell"><span class="tag-dot" style="--tag-color:${t.color};background:${t.color}"></span><div class="tag-meta"><b>${t.name}</b><small>${t.desc}</small></div></div></td><td><span class="group-pill">${t.group}</span></td><td><span class="doc-count" data-open="${t.id}">${t.docs} 篇</span></td><td><span class="type-pill ${t.type.includes('AI')?'ai':''}">${t.type}</span></td><td>${t.time}</td><td><span class="status-pill ${t.enabled?'':'disabled'}">${t.enabled?'已启用':'已停用'}</span></td><td><div class="actions"><button title="查看详情" data-open="${t.id}">${svg('eye')}</button><button class="toggle ${t.enabled?'on':''}" title="${t.enabled?'停用':'启用'}" data-toggle="${t.id}"></button><button title="更多">${svg('more')}</button></div></td></tr>`).join('');empty.style.display=list.length?'none':'block';count.textContent=list.length;}
function svg(n){return `<svg class="icon" viewBox="0 0 24 24">${iconPaths[n]}</svg>`}render();
['searchInput','groupFilter','statusFilter'].forEach(id=>document.querySelector('#'+id).addEventListener(id==='searchInput'?'input':'change',render));
document.querySelector('#clearFilter').onclick=()=>{document.querySelector('#searchInput').value='';document.querySelector('#groupFilter').value='';document.querySelector('#statusFilter').value='';render()};
tbody.addEventListener('click',e=>{const open=e.target.closest('[data-open]'),toggle=e.target.closest('[data-toggle]');if(open)openDrawer(+open.dataset.open);if(toggle){const t=tags.find(x=>x.id===+toggle.dataset.toggle);t.enabled=!t.enabled;render();notify(`标签“${t.name}”已${t.enabled?'启用':'停用'}`)}});
const modal=document.querySelector('#modalOverlay');document.querySelector('#createBtn').onclick=()=>{modal.hidden=false;modal.querySelector('input').focus()};document.querySelectorAll('[data-close]').forEach(x=>x.onclick=()=>modal.hidden=true);modal.onclick=e=>{if(e.target===modal)modal.hidden=true};let picked='#696cff';document.querySelector('#colorPicker').onclick=e=>{const b=e.target.closest('button');if(!b)return;document.querySelectorAll('#colorPicker button').forEach(x=>x.classList.remove('selected'));b.classList.add('selected');picked=b.dataset.color};
document.querySelector('#createForm').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);tags.unshift({id:Date.now(),name:f.get('name'),desc:f.get('description')||'暂无描述',group:f.get('group'),docs:0,type:'手动创建',time:'2026-09-20 '+new Date().toTimeString().slice(0,5),enabled:f.get('enabled')==='on',color:picked});modal.hidden=true;e.target.reset();document.querySelector('#totalStat').textContent=24+tags.length-8;render();notify('标签创建成功')};
function openDrawer(id){const t=tags.find(x=>x.id===id);if(!t)return;document.querySelector('#drawerTitle').textContent=t.name;document.querySelector('#drawerTag').textContent=t.name;document.querySelector('#drawerDot').style.background=t.color;document.querySelector('#drawerStatus').textContent=t.enabled?'已启用':'已停用';document.querySelector('#drawerGroup').textContent=t.group;document.querySelector('#drawerType').textContent=t.type;document.querySelector('#drawerTime').textContent=t.time;document.querySelector('#drawerCount').textContent=t.docs+' 篇';document.querySelector('#relatedDocs').innerHTML=['1.9.指导文章','0.开发架构','5.1.后端状态整理'].map((n,i)=>`<div class="doc-item"><span class="doc-icon">K</span><div><b>${n}</b><small>更新于 2026-09-${18-i} · ${i+2}个标签</small></div></div>`).join('');document.querySelector('#drawerShell').hidden=false}
document.querySelectorAll('[data-drawer-close]').forEach(x=>x.onclick=()=>document.querySelector('#drawerShell').hidden=true);
document.querySelector('#refreshBtn').onclick=e=>{const i=e.currentTarget.querySelector('svg');i.classList.add('spin');setTimeout(()=>{i.classList.remove('spin');notify('数据已更新')},650)};
document.querySelectorAll('.view-tabs button').forEach(b=>b.onclick=()=>{if(b.dataset.view==='library')return;notify(b.dataset.view==='rules'?'智能规则视图已纳入后续设计':'文档打标视图已纳入后续设计')});
function notify(msg){const t=document.querySelector('#toast');t.textContent=msg;t.classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>t.classList.remove('show'),2200)}
document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();document.querySelector('#searchInput').focus()}if(e.key==='Escape'){modal.hidden=true;document.querySelector('#drawerShell').hidden=true}});
